('f76d2706-806b-4c18-a184-fc9733248883', 'Out of the Sand: Ancient Egypt Rediscovered', 'exhibition'::event_type, 'spanning four millennia, a major exhibition bringing together ancient Egyptian artefacts with nineteenth- and twentieth-century paintings, drawings, rare books, and photographs to examine how Egypt was made, buried, recovered, and repeatedly reimagined', array['Out of the Sand']::text[], array['photography','painting','drawing']::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/09/Colnaghi.webp', '2026-09-07', '2026-11-17', null, null, 'Colnaghi', '26 Bury Street, SW1Y 6AL, London', 'SW1Y 6AL', 'West End', 51.50722, -0.139019, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/out-of-the-sand-ancient-egypt-rediscovered/', '2026-11-14T11:48:38.566Z', 0.85, 'out of the sand ancient egypt rediscovered|colnaghi|2026-09-07'),
('ea0462bd-82a2-4b0f-a21d-415eb59a158a', 'Monika Sosnowska: Weight of Matter', 'exhibition'::event_type, 'spanning the Main Gallery and the Fire Station, monumental sculptures made of steel, concrete, and other industrial materials associated with modernist architecture by the Polish artist whose practice explores architecture and urban transformation', array['Monika Sosnowska']::text[], array['installation','sculpture']::text[], array['late','solo show','independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/09/South-London-Gallery-Monika-Sosnowska-1.webp', '2026-09-10', '2026-11-22', null, null, 'South London Gallery', '65-67 Peckham Road, SE5 8UH, London', 'SE5 8UH', 'London', 51.474002, -0.081087, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/monika-sosnowska/', '2026-11-14T11:48:38.566Z', 0.85, 'monika sosnowska weight of matter|south london gallery|2026-09-10'),
('b59ae87f-909d-477d-accb-d1f41963e154', 'Liz Larner: A hard line to bend', 'exhibition'::event_type, 'the first exhibition at a major UK institution of one of the most influential and significant American sculptors of her generation', array['Liz Larner']::text[], array['ceramics','sculpture']::text[], array['solo show','independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/09/Liz-Larner-Different-shade-of-green-2025.jpg', '2026-09-11', '2027-01-17', null, null, 'Camden Art Centre', 'Arkwright Road, NW3 6DG, London', 'NW3 6DG', 'London', 51.551252, -0.183466, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/liz-larner-a-hard-line-to-bend/', '2026-11-14T11:48:38.566Z', 0.85, 'liz larner a hard line to bend|camden art centre|2026-09-11'),
('289ce106-e5c5-4b58-a9c3-3e7dc3de1dbb', 'Under Wraps', 'exhibition'::event_type, 'the inaugural exhibition at the gallery''s new Mayfair home “transforms the act of unveiling into part of the exhibition itself, with significant new works revealed through a choreographed sequence of automated unveilings', '{}'::text[], '{}'::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/09/Charles-Burnand-Under-Wraps-7.webp', '2026-09-12', '2027-01-09', null, null, 'Charles Burnand Gallery', '20 Bruton Place, W1J 6LY, London', 'W1J 6LY', 'London', 51.511266, -0.144662, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/under-wraps/', '2026-11-14T11:48:38.566Z', 0.85, 'under wraps|charles burnand gallery|2026-09-12'),
('6a241328-3257-47de-a6c9-403d74ba863d', 'František Vízner: Beyond the Vessel', 'exhibition'::event_type, 'I have sought to strip away every trace of artistic affectation until my objects reveal themselves as pure crystallisations of natural forces into essential forms” - Vízner', array['František Vízner']::text[], '{}'::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/09/Carpenters-Workshop-London-Frantisek-Vizner-2.webp', '2026-09-17', '2026-12-19', null, null, 'Carpenters', '79 Barlby Road, W10 6AZ, London', 'W10 6AZ', 'London', 51.523712, -0.219534, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/frantisek-vizner-beyond-the-vessel/', '2026-11-14T11:48:38.566Z', 0.85, 'frantisek vizner beyond the vessel|carpenters|2026-09-17'),
('d741ada6-cd74-4358-a79e-c4839259b32b', 'Hernan Bas: TIME TO SHINE! (the salesmen)', 'exhibition'::event_type, 'these new paintings by Bas focus on overlooked characters - “capturing the interactions that make a transaction possible and the brief window that exposes a person\''s vulnerability or confidence', array['Hernan Bas']::text[], array['painting']::text[], array['solo show','hands-on','independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/09/Victoria-Miro-London-Hernan-Bas-2.webp', '2026-09-17', '2026-11-14', null, null, 'Victoria Miro', '16 Wharf Road, N1 7RW, London', 'N1 7RW', 'London', 51.53038, -0.095008, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/hernan-bas-time-to-shine-the-salesmen/', '2026-11-14T11:48:38.566Z', 0.85, 'hernan bas time to shine the salesmen|victoria miro|2026-09-17'),
('d2d090ba-9853-4234-ac88-cdd9e70a5003', 'Vincent Dubourg: Blue Weather', 'exhibition'::event_type, 'sculptural artworks crafted in bronze and wood, anchored by the passage from molten force to settled calm, as Dubourg explores matter as language, power as form, and transformation as a site of meaning', array['Vincent Dubourg']::text[], array['sculpture']::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/09/Carpenters-Workshop-London-Vincent-Dubourg-1.webp', '2026-09-17', '2026-12-19', null, null, 'Carpenters', '79 Barlby Road, W10 6AZ, London', 'W10 6AZ', 'London', 51.523712, -0.219534, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/vincent-dubourg-blue-weather/', '2026-11-14T11:48:38.566Z', 0.85, 'vincent dubourg blue weather|carpenters|2026-09-17'),
('56714382-9837-4940-aa7c-6e6148541735', 'Ce Roser: Running with the Sun, Works 1961-2014', 'exhibition'::event_type, 'paintings and works on paper in the centenarian New York-based artist’s first solo exhibition in Europe - “tracing her remarkable contribution to the language of abstract painting over more than five decades', array['Ce Roser']::text[], array['painting']::text[], array['emerging','independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/VeneKlasen-Ce-Roser-4.webp', '2026-09-18', '2026-12-03', null, null, 'VeneKlasen', '22 Upper Brook Street, W1K 7PZ, London', 'W1K 7PZ', 'London', 51.511356, -0.156072, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/ce-roser-running-with-the-sun-works-1961-2014/', '2026-11-14T11:48:38.566Z', 0.85, 'ce roser running with the sun works 1961 2014|veneklasen|2026-09-18'),
