('86512390-6f51-47ba-a3c9-829f1e82dc53', 'Amar Kanwar', 'exhibition'::event_type, 'a major solo exhibition of the prominent New Delhi-based artist and filmmaker whose distinctive lyrical films move between documentary, travelogue, and visual essay to explore the specific conditions of the Indian subcontinent', '{}'::text[], array['film and video','installation','film']::text[], array['solo show','blockbuster']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/09/Serpentine-North-Amar-Kanwar-1.webp', '2026-09-23', '2027-01-31', null, null, 'Serpentine North Gallery', 'West Carriage Drive, W2 2AR, London', 'W2 2AR', 'London', 51.50707, -0.171261, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/amar-kanwar/', '2026-11-14T11:48:38.566Z', 0.85, 'amar kanwar|serpentine north gallery|2026-09-23'),
('5984e174-9f38-42ee-aebc-3ceff796fff7', 'Richard Baker: Anticipation of Memory', 'exhibition'::event_type, 'an exhibition bringing together works made over the past decade where Baker began painting particular eBay furniture listings he found when moving house “a way of owning something before, or instead of, having it', array['Richard Baker']::text[], array['painting']::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/11/BRINK-Richard-Baker-6.webp', '2026-09-23', '2026-11-14', null, null, 'BRINK', 'The People’s Hall, 2 Olaf Street, W11 4BE, London', 'W11 4BE', 'London', 51.510092, -0.217414, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/richard-baker-anticipation-of-memory/', '2026-11-14T11:48:38.566Z', 0.85, 'richard baker anticipation of memory|brink|2026-09-23'),
('f90b7bbe-9994-4688-a00d-e6cb7d73e0f7', 'Emrys Williams: what seas what shores what grey rocks', 'exhibition'::event_type, 'Emrys knows … that he is ‘dragging things forth’, that they remain a mystery to the rest of us, and only just within his own reach, as passing from memory, like dreams on waking, endlessly reconfigured” - John Gillett', array['Emrys Williams']::text[], '{}'::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/09/Benjamin-Rhodes-Emrys-Williams-1.webp', '2026-09-24', '2026-11-21', null, null, 'Benjamin Rhodes Arts', '62 Old Nichol Street, E2 7HP, London', 'E2 7HP', 'London', 51.52496, -0.074245, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/emrys-williams-what-seas-what-shores-what-grey-rocks/', '2026-11-14T11:48:38.566Z', 0.85, 'emrys williams what seas what shores what grey rocks|benjamin rhodes arts|2026-09-24'),
('baa5338d-84c5-4ee7-a43c-57dac7ce0352', 'Jonathan Baldock: For Your Keeping', 'exhibition'::event_type, 'a new body of small-scale works in the form of votive objects, keepsakes, and bodily hybrids made in ceramic and textile', array['Jonathan Baldock']::text[], array['ceramics','textiles']::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/OH_1166d-49.jpg', '2026-09-24', '2026-11-20', null, null, 'Canopy Collections', '3 Bloomsbury Place, WC1A 2QA, London', 'WC1A 2QA', 'London', 51.519847, -0.122749, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/jonathan-baldock-for-your-keeping/', '2026-11-14T11:48:38.566Z', 0.85, 'jonathan baldock for your keeping|canopy collections|2026-09-24'),
('f4e3ae25-a6a9-4e13-a894-0d8862122478', 'Evelyn Taocheng Wang: Being Poetic Ruins Life', 'exhibition'::event_type, 'Opening: Thursday 24 September, 6—9pm “I see the womb as an organ which provides possibility. I think this womb protects me and gives me shelter. It gave me a certain freedom.“ — Evelyn Taocheng Wang Goldsmiths Centre for Contemporary Art presents Being Poetic Ruins Life, the first UK institutional exhibition by Netherlands-based artist, Evelyn Taocheng Wang (b. 1981, Chengdu, China). The exhibition, staged across the CCA’s entire building, offers a comprehensive presentation of Wang’s practice', array['Evelyn Taocheng Wang']::text[], array['film and video','installation','painting','textiles']::text[], array['solo show','community','cultural events','exhibition','museums galleries','visual arts','independent']::text[], 'https://www.wearelewisham.com/media/cache/7b/7b/7b7ba728c5ad9e04aede179022e30771.jpg', '2026-09-25', '2026-12-13', '12:00:00', null, 'Goldsmiths CCA', 'St James’, New Cross, London SE14 6AD', 'SE14 6AD', 'New Cross', 51.474219, -0.038799, 'free'::price_type, 0, true, 'https://goldsmithscca.art/exhibition/evelyn-taocheng-wang/', 'Arts Calendar', 'https://artscalendar.co.uk/exhibitions/evelyn-taocheng-wang-being-poetic-ruins-life/', '2026-11-14T11:48:40.128Z', 0.75, 'evelyn taocheng wang being poetic ruins life|goldsmiths cca|2026-09-25'),
('14c9eecb-9602-445d-a7ad-8668fc41176a', 'Hugo Winder-Lind: 140 Knights in Silver Armour', 'exhibition'::event_type, 'the debut of ambitious sculptural and video work as Winder-Lind draws both on a 19th century English fable and the fabric of the gallery to create an entire world rendered in vivid and whimsical detail', array['Hugo Winder-Lind']::text[], array['sculpture','film']::text[], array['emerging','independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/Robbie-von-Kampen.webp', '2026-09-25', '2026-11-14', null, null, 'Robbie von Kampen', '31 Old Compton Street, 1st Floor, W1D 5JS, London', 'W1D 5JS', 'London', 51.51298, -0.131434, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/hugo-winder-lind-140-knights-in-silver-armour/', '2026-11-14T11:48:38.566Z', 0.85, 'hugo winder lind 140 knights in silver armour|robbie von kampen|2026-09-25'),
