('b4ee92b6-2eca-4c80-af60-047f2a516ac3', 'Reko Rennie: Renaissance Revolution', 'exhibition'::event_type, 'the Aboriginal artist’s first London exhibition begins with a childhood memory of visits to Melbourne’s National Gallery of Victoria and questions who is represented in museums, who decides, and who is left out', array['Reko Rennie']::text[], '{}'::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/26-9_Yavuz-Rennie_3b.jpg', '2026-10-08', '2026-11-14', null, null, 'Ames Yavuz', '31 Grosvenor Hill, W1K 3QU, London', 'W1K 3QU', 'West End', 51.511612, -0.145483, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/reko-rennie-renaissance-revolution/', '2026-11-14T11:48:38.566Z', 0.85, 'reko rennie renaissance revolution|ames yavuz|2026-10-08'),
('dcc65166-b722-4944-adf3-8f239485ac8d', 'Romuald Hazoumè: My Blue Period', 'exhibition'::event_type, 'addressing historical and modern slavery, migration, and the brutal realities of postcolonial Africa, the internationally renowned artist’s iconic masks made of repurposed plastic containers reflect on the precarious nature of the world we inhabit', array['Romuald Hazoumè']::text[], '{}'::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/October-Gallery-Romuald-Hazoume-1.webp', '2026-10-08', '2026-11-21', null, null, 'October Gallery', '24 Old Gloucester Street, Bloomsbury, WC1N 3AL, London', 'WC1N 3AL', 'London', 51.520694, -0.121705, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/romuald-hazoume-my-blue-period/', '2026-11-14T11:48:38.566Z', 0.85, 'romuald hazoume my blue period|october gallery|2026-10-08'),
('47f5e006-e360-4520-af75-18852264037b', 'Tim Garwood: Signals', 'exhibition'::event_type, 'bringing together paintings on birch panel, painted photographs and installation in the form of steel agricultural gates, the exhibition explores what it means to look closely, to slow down and to become attentive to one’s surroundings', array['Tim Garwood']::text[], array['photography','painting','installation']::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/Sim-Smith-Tim-Garwood-1.webp', '2026-10-08', '2026-11-21', null, null, 'Sim Smith', '6 Camberwell Passage, SE5 0AX, London', 'SE5 0AX', 'London', 51.474874, -0.094312, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/tim-garwood-2/', '2026-11-14T11:48:38.566Z', 0.85, 'tim garwood signals|sim smith|2026-10-08'),
