('8359177c-22ff-4852-ab9a-da1f1b734cfd', 'Monotype printing', 'workshop'::event_type, 'Explore the expressive and experimental world of monotype printmaking in this engaging five-week course. Combining elements of drawing and painting, monotype allows you to create unique, one-off prints through a range of creative techniques. You will learn how to prepare and use printing inks, experiment with layering colour, and develop images using additive and reductive methods. Through processes such as stencil work, trace monotype, and ghost printing, you''ll create rich textures, atmospheri', '{}'::text[], array['printmaking','painting','drawing']::text[], array['community','hands-on','independent']::text[], 'https://www.wearelewisham.com/media/cache/8e/aa/8eaa01a6532f0d315184f0e55c84f3b6.jpg', '2026-11-12', '2026-12-10', '13:00:00', null, 'Adult Learning Lewisham', 'Adult Learning Lewisham, Granville Park Centre, 100 Granville Park, SE13 7DU', 'SE13 7DU', 'Lewisham', 51.46543, -0.01021, 'unknown'::price_type, null, true, 'https://all.org.uk/courses/printing/#course-89009', 'We Are Lewisham', 'https://www.wearelewisham.com/events/monotypeprinting/', '2026-11-14T11:48:39.377Z', 0.75, 'monotype printing|adult learning lewisham|2026-11-12'),
