('1f455ece-40b3-4754-af85-34a5b0ee1691', 'Drawing with charcoal', 'workshop'::event_type, 'Discover the creative possibilities of charcoal in this enjoyable one-day workshop. Learn essential drawing techniques, experiment with this versatile medium, and build confidence in creating expressive artwork. Working from photographs or personal objects, you''ll develop your own composition while exploring tone, texture, and mark-making. Cost: £48.75 (full fee), £28.75 (reduced fee)', '{}'::text[], array['photography','drawing']::text[], array['community','hands-on','independent']::text[], 'https://www.wearelewisham.com/media/cache/08/d7/08d7452a95d12dbc654bd3144939d73d.jpg', '2026-11-21', null, '10:00:00', '15:30:00', 'Brockley Rise Adult Education Centre', 'Brockley Rise Adult Education Centre, 2 Brockley Rise, SE23 1PR', 'SE23 1PR', 'Lewisham', 51.44388, -0.04229, 'unknown'::price_type, null, true, 'https://all.org.uk/courses/drawing-painting-and-watercolour-one-day-and-taster-courses/#course-87822', 'We Are Lewisham', 'https://www.wearelewisham.com/events/drawingwithcharcoal/', '2026-11-14T11:48:39.377Z', 0.75, 'drawing with charcoal|brockley rise adult education centre|2026-11-21'),
