('c9e6b54b-7475-443d-a3c5-d826dd1aa92e', 'TTRPGs & Monster Drawing Workshop', 'workshop'::event_type, 'Iglootree returns to Manor House Library for a day of tabletop role-playing games! Join us on Saturday 21st November for an expo of TTRPGs and a workshop where you’ll learn to draw your very own monster. All ages are welcome, but we strongly recommend players be 12+ or comfortable with perilous themes. All games will begin at 10:30am. There will be four different tables to choose from on the day. Drawing workshops run in 90 minute sessions, so please book your preferred timeslot. This event is f', '{}'::text[], array['drawing','digital']::text[], array['community','family friendly','libraries','hands-on','independent']::text[], 'https://www.wearelewisham.com/media/cache/2b/3b/2b3bea51a98670cfa4874996f13e169d.png', '2026-11-21', null, '10:30:00', '15:30:00', 'Manor House Library', 'Manor House Library, 34 Old Road, SE13 5SY', 'SE13 5SY', 'Lewisham', 51.457723, 0.003821, 'free'::price_type, 0, true, 'https://buytickets.at/calico/2442671', 'We Are Lewisham', 'https://www.wearelewisham.com/events/ttrpgsmonsterdrawingworkshop/', '2026-11-14T11:48:39.377Z', 0.75, 'ttrpgs monster drawing workshop|manor house library|2026-11-21'),
