('e9bf844c-6548-4306-a8a6-b5092cfbb1db', 'Andreas Stylianou: Extinction Point', 'exhibition'::event_type, 'spanning ceramics, metal and neon, the exhibition considers the point as both a mark and a moment: something carved, excavated, recorded, created or reached', array['Andreas Stylianou']::text[], array['sculpture','ceramics']::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/05-Moon-Landing-X-frontLOW.jpeg', '2026-11-22', null, null, null, 'THE TAGLI', '67 Great Titchfield Street, W1W 7PT, London', 'W1W 7PT', 'West End', 51.518923, -0.140949, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/extinction-point/', '2026-11-14T11:48:38.566Z', 0.85, 'andreas stylianou extinction point|the tagli|2026-11-22'),
