('61fb9d0c-05c8-49c6-a2b7-28e7fe44442f', 'Peggy Guggenheim in London', 'exhibition'::event_type, 'In the late 1930s, Peggy Guggenheim launched an art gallery in Mayfair that shocked the conservative tastes of the British art establishment. This exhibition revisits the gallery that helped redefine London’s contemporary art scene.', '{}'::text[], '{}'::text[], array['late','blockbuster']::text[], null, '2026-11-22', '2027-03-14', null, null, 'Royal Academy of Arts', null, 'W1J 0BD', 'Picadilly', 51.509099, -0.139576, 'paid'::price_type, 19.5, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/peggy-guggenheim-in-london-434831/', '2026-11-14T11:48:44.390Z', 0.8, 'peggy guggenheim in london|royal academy of arts|2026-11-22'),
