('89e6d93e-e5a0-45d0-a40a-e66f3ef5047b', 'Tove Jansson and her Families', 'exhibition'::event_type, 'Uncovering the personal relationships behind the celebrated artist, this exhibition will look at the people who shaped Finnish author-illustrator Tove Jansson’s life and work – the UK’s first ever exhibition to focus on Tove Jansson’s work as an illustrator.', '{}'::text[], array['illustration']::text[], array['family','independent']::text[], 'data:image/svg+xml,%3Csvg%20xmlns=''http://www.w3.org/2000/svg''%20viewBox=''0%200%20150%20150''%3E%3C/svg%3E', '2026-11-22', '2027-05-09', null, null, 'Quentin Blake Centre for Illustration', null, 'EC1R 1AG', 'Clerkenwell', 51.528594, -0.1076445, 'paid'::price_type, 15, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/tove-jansson-and-her-families-434846/', '2026-11-14T11:48:44.390Z', 0.8, 'tove jansson and her families|quentin blake centre for illustration|2026-11-22'),
('7b747987-d158-4a6d-aec5-264223d5dfc8', 'Youth Dance Day', 'workshop'::event_type, 'Join us for a FREE day of dance, with activities for beginner and experienced dancers in School Years 7-11. Dancers will be grouped with peers of a similar age to support and progress your dance skills and knowledge through a series of classes, workshops, and performances. If you love to dance, this event is for you! Join us for an action-packed day to include: - Taster sessions in different dance styles including Hip Hop and Contemporary. - Masterclasses for experienced young dancers. - Creativ', '{}'::text[], array['performance']::text[], array['community','creative health','dance','free','hands-on','independent']::text[], 'https://www.wearelewisham.com/media/cache/4c/80/4c8047203e074213496086118135a803.jpg', '2026-11-22', null, '10:00:00', '16:00:00', 'Laban Building', 'Laban Building, Deptford, London, SE8 3DZ', 'SE8 3DZ', 'Lewisham', 51.479053, -0.020414, 'free'::price_type, 0, true, 'https://www.trinitylaban.ac.uk/whats-on/youth-dance-day/', 'We Are Lewisham', 'https://www.wearelewisham.com/events/youthdanceday/', '2026-11-14T11:48:40.149Z', 0.75, 'youth dance day|laban building|2026-11-22'),
