('17132227-87c2-4f19-a116-3ed0b64e15a2', 'Creative Hub - Find Your Voice (for boys aged 10 - 14)', 'workshop'::event_type, 'Through acting, improvisation, storytelling, creative writing and spoken word, you will learn how to turn your own experiences, ideas and imaginations into original performances. Inspired by the creative development of ''Drive'' (an original British theatre production that has transferred to London’s West End and is now touring nationally), the workshop will explore themes of friendship, identity, masculinity, ambition and belonging, encouraging you to celebrate your individuality and discover the', '{}'::text[], array['performance']::text[], array['community','creative health','shows theatre','working with schools','hands-on','independent']::text[], 'https://www.wearelewisham.com/media/cache/8f/1c/8f1c54c00d107272c3fe75d9df07893c.png', '2026-11-25', null, '17:00:00', '19:00:00', 'Lewisham Youth Theatre', 'Lewisham Youth Theatre, 436 Lewisham High Street, SE13 6LJ', 'SE13 6LJ', 'Lewisham', 51.450978234863335, -0.0175845623016357, 'free'::price_type, 0, true, 'https://www.eventbrite.com/e/2004217617847?aff=oddtdtcreator', 'We Are Lewisham', 'https://www.wearelewisham.com/events/creativehubfindyourvoiceforboysaged1014/', '2026-11-14T11:48:40.149Z', 0.75, 'creative hub find your voice for boys aged 10 14|lewisham youth theatre|2026-11-25'),
('eb0d4c42-a9e8-4218-af86-f4fb8f8abb91', 'Freudian Research Seminar – Capital, Delay, Body: Laura Mulvey’s Freud', 'talk'::event_type, 'All registrants will receive their link to join via ZOOM. Attendees will also receive access to the recording on the Monday after the event, available to watch back for 3 months. ________________________________________________________________________ Abstract: Considering three periods of her work, this talk will explore how Laura Mulvey has applied Freudian psychoanalysis to each of them, but more crucially will consider how Mulvey has used the technological changes of each historical moment to respond to and rethink Freud’s work. Beginning by briefly outlining Mulvey’s account of the relati', '{}'::text[], '{}'::text[], array['community','independent']::text[], 'https://www.freud.org.uk/wp-content/uploads/2020/01/HP-12.jpg', '2026-11-25', null, '18:00:00', '19:30:00', 'Online', null, 'W3 9BD', 'Hampstead', 51.501385, -0.2849707, 'unknown'::price_type, null, null, null, 'Freud Museum', 'https://www.freud.org.uk/event/freudian-research-seminar-capital-delay-body-laura-mulveys-freud/', '2026-11-14T11:49:07.661Z', 0.7, 'freudian research seminar capital delay body laura mulvey s freud|online|2026-11-25'),
