('005e5153-02c2-40c1-aa71-206ae429c190', 'The 544: A photographic memorial', 'exhibition'::event_type, 'This exhibition features 544 individual cyanotype photographic images to symbolise and bring individuality to 544 anonymous people who have become forever grouped together as victims of a horrific mass murder at the Daugavpils psychiatric hospital in Latvia in 1941.', '{}'::text[], array['photography']::text[], array['independent']::text[], 'data:image/svg+xml,%3Csvg%20xmlns=''http://www.w3.org/2000/svg''%20viewBox=''0%200%20150%20150''%3E%3C/svg%3E', '2026-11-26', '2027-03-06', null, null, 'Bethlem Museum of the Mind', null, 'BR3 3BX', 'Beckenham', 51.377782, -0.029228, 'free'::price_type, 0, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/the-544-a-photographic-memorial-436293/', '2026-11-14T11:48:46.750Z', 0.8, 'the 544 a photographic memorial|bethlem museum of the mind|2026-11-26'),
