('1e7622cd-9aec-43c3-a24e-6a542ae8b654', 'Making the Clinic: Spatial and Material Investigations, Artist Talk with Ana Čvorović', 'talk'::event_type, 'The Freud Museum is delighted to host an artist talk by Ana Čvorović, whose work is displayed at the Museum, in an exhibition curated by Sacha Craddock (November 16-December 6 2026). The talk will be followed by a wine reception (9pm – 10pm). In this artist talk, Ana Čvorović discusses the work she developed through her research with FREEPSY – Free Clinics and Psychoanalysis for the People, bringing together earlier iterations of the work made during the project with the new sculpture and sound installation exhibited at the Freud Museum. Taking the works as a starting point, Čvorović reflects', '{}'::text[], array['sculpture','installation','sound']::text[], array['community','hands-on','free','independent']::text[], 'https://www.freud.org.uk/wp-content/uploads/2026/09/Screenshot-2026-09-23-155647.png', '2026-11-27', null, '19:00:00', '21:00:00', 'Freud Museum London', '20 Maresfield Gardens, London', 'NW3 5SX', 'Hampstead', 51.548838, -0.177417, 'paid'::price_type, 11.13, null, null, 'Freud Museum', 'https://www.freud.org.uk/event/making-the-clinic-spatial-and-material-investigations-artist-talk-with-ana-cvorovic/', '2026-11-14T11:49:07.661Z', 0.7, 'making the clinic spatial and material investigations artist talk with ana cvorovic|freud museum london|2026-11-27'),
('50ba11ed-1412-483f-a635-3ba275a7d766', 'Stanley Arts Christmas Market', 'fair'::event_type, 'The stalls are set and our traders are keen to bring you magical gifts this Christmas for the whole family! These markets will feature local arts, crafts and produce so you can find the perfect Christmas gifts, all in one place. Ceramics, stocking fillers, jewellery, homemade crafts, candles – you name it and we’ll have it. In the grand indoor space that is the main hall, get into the Christmas spirit with mulled wine, mince pies, and all the gifts you could want to give. Friday: 5pm – 9pm Saturday: 10am – 4pm On Friday the 27th between 7:30pm – 8:30pm, our Christmas Lights Switch On will be t', '{}'::text[], array['ceramics']::text[], array['community','family','independent']::text[], 'https://stanleyarts.org/wp-content/uploads/2026/10/Christmas-Market-Feature.png', '2026-11-27', null, '17:00:00', '21:00:00', 'Stanley Hall', null, 'SE25 6EG', 'South Norwood', 51.4001164, -0.0755514, 'unknown'::price_type, null, null, null, 'Stanley Arts', 'https://stanleyarts.org/event/stanley-arts-christmas-market/2026-11-27/', '2026-11-14T11:49:08.248Z', 0.7, 'stanley arts christmas market|stanley hall|2026-11-27'),
('5b12da61-ae75-49bb-a63f-14949f5194be', 'Cherrystars Performing Arts', 'workshop'::event_type, 'Cherrystars are an award winning, community performing arts school. Their team consist of BRIT School alumni and professional television and theatre actors who specialise in teaching innovative performing arts classes to the early years.', '{}'::text[], array['performance']::text[], array['community','hands-on','independent']::text[], 'https://stanleyarts.org/wp-content/uploads/2024/05/Cherrystars-feature-event-image.png', '2026-11-28', null, '09:30:00', '12:00:00', 'Stanley Hall', null, 'SE25 6EG', 'South Norwood', 51.4001164, -0.0755514, 'unknown'::price_type, null, null, 'https://cherrystars.classforkids.io/', 'Stanley Arts', 'https://stanleyarts.org/event/cherrystars-performing-arts-3-2-2-2/2026-11-28/', '2026-11-14T11:49:08.248Z', 0.7, 'cherrystars performing arts|stanley hall|2026-11-28'),
