('3d8e3f01-2bc9-4a67-a829-6cd0e6b191b0', 'Bedlam: Stanley Arts Fundraiser', 'other'::event_type, 'NHS big band Bedlam will perform live at Stanley Arts on Friday 4th November 7.30pm. This charity event will raise critical funds to continue our Dance for Health programme and support urgent building repairs.', '{}'::text[], array['performance']::text[], array['community','independent']::text[], 'https://stanleyarts.org/wp-content/uploads/2026/10/bedlam-1240x826-1.jpg', '2026-12-04', null, '19:30:00', '21:15:00', 'Stanley Hall', null, 'SE25 6EG', 'South Norwood', 51.4001164, -0.0755514, 'unknown'::price_type, null, null, 'https://stanleyarts.ticketsolve.com/ticketbooth/shows/1173694950', 'Stanley Arts', 'https://stanleyarts.org/event/bedlam-stanley-arts-fundraiser/', '2026-11-14T11:49:08.248Z', 0.7, 'bedlam stanley arts fundraiser|stanley hall|2026-12-04'),
('35e1b58c-4074-44ce-afc0-4cbbd5803adf', 'Cockpit Open Studios: Winter 2026 Deptford', 'open_studio'::event_type, 'Enjoy a festive day out at Cockpit Winter Open Studios – an exceptional showcase of craft and making and your chance to meet and buy unique gifts from over 175 of London’s finest artist-makers. This annual shopping event is the only time Cockpit Studios – an award-winning charity – opens its doors to the public, offering an exclusive opportunity to meet makers in their studios, shop local, and enjoy festive community cheer while supporting independent businesses with your holiday gifting. From j', '{}'::text[], array['craft']::text[], array['makers','craft','independent','community','cultural events','exhibition','support for artists','visual arts','hands-on']::text[], 'https://cockpitstudios.org/wp-content/uploads/2026/09/sofi-chetrar-ca-deptford-winter-2025-203-768x512.jpg', '2026-12-04', '2026-12-06', '17:00:00', null, 'Cockpit Deptford', 'Cockpit Deptford, 18-22 Creekside, London SE8 3DZ', 'SE8 3DZ', 'Deptford', 51.47845355323102, -0.0206476449966431, 'unknown'::price_type, null, true, 'https://cockpitstudios.org/whats-on/winter-2026-deptford/', 'Cockpit Studios', 'https://cockpitstudios.org/whats-on/winter-2026-deptford/', '2026-11-14T11:48:39.032Z', 0.75, 'cockpit open studios winter 2026 deptford|cockpit deptford|2026-12-04'),
('d85ddf58-48e6-45d6-a01f-fcf5db2d0d15', 'Gallery White Box Winter Show ''26', 'exhibition'::event_type, 'Please gather for Gallery White Box''s annual winter show, a group exhibition of paintings and other works of fine art with a seasonal flavour. Featuring popular established and up-and-coming local artists from Blackheath and wide South East London, the show offers a chance to feel inspired and admire the craft and wonder of the area''s fine art scene and potentially purchase a unique gift for a loved one or to brighten the home. Gallery White Box is on the edge of the heath, a six-minute walk fro', '{}'::text[], array['painting']::text[], array['community','creative businesses','cultural events','exhibition','museums galleries','visual arts','christmas','outdoor','independent']::text[], 'https://www.wearelewisham.com/media/cache/82/b8/82b8d3d55eec51e7d7222cd1b9856f4a.jpg', '2026-12-04', '2026-12-20', '12:00:00', null, '5 Hare and Billet Road', '5 Hare and Billet Road, Blackheath, SE3 0RB', 'SE3 0RB', 'Lewisham', 51.46798581172755, 0.0039602816104889, 'free'::price_type, 0, true, 'https://gallerywhitebox.co.uk/', 'We Are Lewisham', 'https://www.wearelewisham.com/events/gallerywhiteboxwintershow26/', '2026-11-14T11:48:40.149Z', 0.75, 'gallery white box winter show 26|5 hare and billet road|2026-12-04'),
