('7a87d65f-c7d0-4c05-aa1a-555eb3277768', 'Annual Open Studios and Pottery Sale', 'open_studio'::event_type, 'We can’t wait to welcome you to our studio for this year’s open studios event! Step into the heart of our creative space and celebrate the winter season with us. This is a wonderful opportunity to: • Explore our pottery studio and experience live technique demonstrations • Support local established and emerging makers • Purchase unique, handcrafted pottery—perfect for gifts or personal collections Enjoy a warm, festive atmosphere with mulled wine, seasonal treats, and inspiring creativity all ar', '{}'::text[], array['ceramics']::text[], array['community','artist studios','cultural events','exhibition','visual arts','christmas','emerging','outdoor','independent']::text[], 'https://www.wearelewisham.com/media/cache/78/95/7895c1dad4fa44b3c556b94b8f344101.jpg', '2026-12-05', null, '13:00:00', '18:00:00', '73-79 Childers Street', '73-79 Childers Street, SE8 5JR, Deptford', 'SE8 5JR', 'Lewisham', 51.48169, -0.03345, 'free'::price_type, 0, true, 'https://www.ceramicsstudio.coop/open-studios-2026', 'We Are Lewisham', 'https://www.wearelewisham.com/events/annualopenstudiosandpotterysale/', '2026-11-14T11:48:40.907Z', 0.75, 'annual open studios and pottery sale|73 79 childers street|2026-12-05'),
('053a55c7-775e-443d-a12b-69c48033b104', 'Cherrystars Performing Arts', 'workshop'::event_type, 'Cherrystars are an award winning, community performing arts school. Their team consist of BRIT School alumni and professional television and theatre actors who specialise in teaching innovative performing arts classes to the early years.', '{}'::text[], array['performance']::text[], array['community','hands-on','independent']::text[], 'https://stanleyarts.org/wp-content/uploads/2024/05/Cherrystars-feature-event-image.png', '2026-12-05', null, '09:30:00', '12:00:00', 'Stanley Hall', null, 'SE25 6EG', 'South Norwood', 51.4001164, -0.0755514, 'unknown'::price_type, null, null, 'https://cherrystars.classforkids.io/', 'Stanley Arts', 'https://stanleyarts.org/event/cherrystars-performing-arts-3-2-2-2/2026-12-05/', '2026-11-14T11:49:08.248Z', 0.7, 'cherrystars performing arts|stanley hall|2026-12-05'),
('2517b1bb-5567-43c1-a578-0dfc0c82b5c4', 'FUSS Fair', 'fair'::event_type, 'Come and hear Quaggy Community Choir sing at the FUSS Xmas Fair. We will be on around 1.30pm and will sing a range of songs of different types, arranged by our talented Musical Director, Jake Alexander. There will be lots of other wonderful musical performances as well as food and craft stalls. I always find something special to buy for my family for Xmas there.', '{}'::text[], '{}'::text[], array['community','choir','creative businesses','creative health','cultural events','family friendly','festivals','gigs','live music','market','music','support for artists','christmas','family','independent']::text[], 'https://www.wearelewisham.com/media/cache/9e/3f/9e3f78450e69bb19ddbe1d6ec67fd8a4.jpg', '2026-12-05', null, '12:00:00', '17:00:00', 'Hither Green Station', 'Hither Green Station, 9 Staplehurst Road', 'SE13 6HE', 'Lewisham', 51.45239342342628, -0.0012014137162519, 'free'::price_type, 0, true, 'https://www.quaggycommunitychoir.com/', 'We Are Lewisham', 'https://www.wearelewisham.com/events/fussfair/', '2026-11-14T11:48:40.907Z', 0.75, 'fuss fair|hither green station|2026-12-05'),
