('2df1bea5-ea76-4ec7-abac-f2b809b30fb2', 'Sunday Writing Sessions: Wintering', 'workshop'::event_type, 'What does wintering mean to you? Find inspiration in Katherine May, Tove Jansson and more at The Grove’s cosy, creative writing session. Everyone welcome!', '{}'::text[], '{}'::text[], array['artist-run','independent','hands-on']::text[], 'https://i0.wp.com/setspace.uk/wp-content/uploads/2026/10/Dec-Sunday-Session.png?fit=1080%2C1350&ssl=1', '2026-12-13', null, '12:00:00', '13:45:00', 'SET Social', '55a Nigel Road, London', 'SE15 4NP', 'Southwark', 51.4663636, -0.0667924, 'paid'::price_type, 9, null, null, 'SET', 'https://setspace.uk/event/sunday-writing-sessions-wintering/', '2026-11-14T11:49:07.573Z', 0.7, 'sunday writing sessions wintering|set social|2026-12-13'),
('03caebf3-8887-4af9-a511-1f8426d2bb40', 'Christmas Holiday Class - Block Printing Elf Style - Family Class (3+)', 'workshop'::event_type, 'Personalise your gift wrapping this year with a signature touch of your kid''s creativity, by block printing your wrapping paper and gift tags, elf style! Work together to create your design by cutting out shapes of foam to glue to your base, then start the elf production line! You''ll be inking and printing your wrapping for all the family using this traditional printing technique made easy. Santa''s elves will be jealous! This class is appropriate for children 3+ but children of all ages are most', '{}'::text[], '{}'::text[], array['community','christmas','family','hands-on','independent']::text[], 'https://www.wearelewisham.com/media/cache/e9/1d/e91dc41d5951b031ca0c76a915388393.jpg', '2026-12-14', null, '09:30:00', '12:30:00', '19-21 Lee Road', '19-21 Lee Road, London, SE3 9RQ', 'SE3 9RQ', 'Lewisham', 51.46463, 0.00941, 'unknown'::price_type, null, true, 'https://shop.conservatoire.org.uk/product/prd_GfUQZStaykeDIgGhWLKTVg', 'We Are Lewisham', 'https://www.wearelewisham.com/events/christmasholidayclassblockprintingelfstylefamily/', '2026-11-14T11:48:40.907Z', 0.75, 'christmas holiday class block printing elf style family class 3|19 21 lee road|2026-12-14'),
